package logicscript.ast;

/**
 * Generated by the parser's tag function to indicate the source-code location of a specific AST object.
 *
 * @author Lochie
 */
public class Location {

    public final int beginLine, endLine;
    public final int beginCol, endCol;

    public final String token;

    public Location(String t, int bl, int el, int bc, int ec) {
	this.token = t;
	this.beginLine = bl;
	this.beginCol = bc;
	this.endLine = el;
	this.endCol = ec;
    }

    @Override
    public String toString() {
	StringBuilder builder = new StringBuilder();
	if (this.token != null)
	    builder.append("token `").append(this.token).append("` ");
	builder.append("at line ").append(this.beginLine).append(" ");
	builder.append("column ").append(this.beginCol).append(":").append(this.endCol);
	builder.append(" (").append(this.endCol - this.beginCol).append(" char(s))");
	return builder.toString();
    }
}
